+#[cfg(test)]
+mod tests {
+    use crate::openapi::{LoadedYaml, load_yaml};
+
+    #[test]
+    fn simple_json_endpoint() {
+        let yaml: &str = r##"
+            openapi: 3.0.4
+            paths:
+                /pets/{pet-id}:
+                    get:
+                        description: Return information about a pet.
+                        responses:
+                            '2XX':
+                                $ref: "#/components/schemas/pet"
+            components:
+                schemas:
+                    pet:
+                        type: object
+                        properties:
+                            name:
+                                type: string
+                                description: The name of the pet.
+                                nullable: false
+                requestBodies:
+                    petRequestBody:
+                        description: Request body for pets.
+                        content:
+                            application/json:
+                                schema:
+                                    $ref: "#/components/schemas/pet"
+            "##;
+
+        let LoadedYaml { paths, schemas } = load_yaml(yaml).unwrap();
+
+        println!("{schemas:?}");
+
+        assert_eq!(paths.len(), 1);
+        assert_eq!(schemas.len(), 2);
+    }
+
+    #[test]
+    fn media_query_endpoint() {
+        let yaml: &str = r##"
+            openapi: 3.0.4
+            paths:
+                /pets/{pet-id}/$value:
+                    get:
+                        description: Return the pet's noise.
+                        responses:
+                            '2XX':
+                                description: .wav with the pet's noise.
+                                content:
+                                    application/octet-stream:
+                                        schema:
+                                            type: string
+                                            format: binary
+                    put:
+                        description: Change the pet's noise.
+                        responses:
+                            2XX:
+                                description: Success
+        "##;
+
+        let LoadedYaml { paths, .. } = load_yaml(yaml).unwrap();
+
+        println!("{paths:?}");
+
+        assert_eq!(paths.len(), 1);
+    }
+}
